'use client';

import {
  useLayoutEffect,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
} from 'react';
import { usePlayback } from './use-playback';
import './text-marquee.css';

export interface TextMarqueeProps {
  items: string[];
  /** Accessible name for the list. */
  label: string;
  /** Pixels per second. */
  speed?: number;
  direction?: 'left' | 'right';
  paused?: boolean;
  className?: string;
}

const useIsomorphicLayoutEffect =
  typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * Labels scroll through a track forever. The moving track is two decorative
 * copies; assistive technology reads one plain list. It stops when paused,
 * off screen, in a hidden tab, or with reduced motion (it then wraps).
 */
export function TextMarquee({
  items,
  label,
  speed = 60,
  direction = 'left',
  paused = false,
  className = '',
}: TextMarqueeProps) {
  const root = useRef<HTMLDivElement>(null);
  const copy = useRef<HTMLUListElement>(null);
  const [width, setWidth] = useState(0);
  const playing = usePlayback(root, paused);

  useIsomorphicLayoutEffect(() => {
    const el = copy.current;
    if (!el) return;
    const measure = () => setWidth(el.offsetWidth);
    measure();
    if (typeof ResizeObserver === 'undefined') return;
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [items]);

  const duration = width > 0 ? width / Math.max(1, speed) : 20;
  const list = (hidden: boolean) => (
    <ul
      ref={hidden ? undefined : copy}
      className='mg-marquee__copy'
      aria-hidden='true'
    >
      {items.map((item, index) => (
        <li key={index}>{item}</li>
      ))}
    </ul>
  );

  return (
    <div
      ref={root}
      className={`mg-marquee ${className}`}
      data-playing={playing}
      data-direction={direction}
      style={{ '--mg-duration': `${duration}s` } as CSSProperties}
    >
      <ul className='mg-marquee__sr' aria-label={label}>
        {items.map((item, index) => (
          <li key={index}>{item}</li>
        ))}
      </ul>
      <div className='mg-marquee__track'>
        {list(false)}
        {list(true)}
      </div>
    </div>
  );
}

.mg-marquee {
  overflow: hidden;
  -webkit-mask-image: linear-gradient(
    90deg,
    transparent,
    #000 10%,
    #000 90%,
    transparent
  );
  mask-image: linear-gradient(
    90deg,
    transparent,
    #000 10%,
    #000 90%,
    transparent
  );
}

.mg-marquee__track {
  display: flex;
  width: max-content;
  animation: mg-marquee-left var(--mg-duration) linear infinite;
  animation-play-state: paused;
}

.mg-marquee[data-playing='true'] .mg-marquee__track {
  animation-play-state: running;
}

.mg-marquee[data-direction='right'] .mg-marquee__track {
  animation-direction: reverse;
}

.mg-marquee__copy {
  display: flex;
  flex: none;
  gap: 10px;
  margin: 0;
  padding: 0 10px 0 0;
  list-style: none;
}

.mg-marquee__copy li {
  padding: 8px 14px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 999px;
  background: #121212;
  color: var(--mg-text, #ffffff);
  font-weight: 600;
  white-space: nowrap;
}

.mg-marquee__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: 0;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

@keyframes mg-marquee-left {
  to {
    transform: translateX(-50%);
  }
}

/* No movement: show one copy, wrapped onto several lines. */
@media (prefers-reduced-motion: reduce) {
  .mg-marquee {
    -webkit-mask-image: none;
    mask-image: none;
  }
  .mg-marquee__track {
    width: auto;
    animation: none;
  }
  .mg-marquee__copy {
    flex-wrap: wrap;
    padding: 0;
  }
  .mg-marquee__copy + .mg-marquee__copy {
    display: none;
  }
}

'use client';

import { useEffect, useState, type RefObject } from 'react';

/**
 * Whether a continuous effect should run: its element is on screen, the
 * browser tab is visible and the caller has not paused it. Loops should stop
 * (or set `animation-play-state: paused`) whenever this returns false.
 */
export function usePlayback(
  ref: RefObject<Element | null>,
  paused = false
): boolean {
  const [onScreen, setOnScreen] = useState(false);
  const [pageVisible, setPageVisible] = useState(true);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === 'undefined') {
      setOnScreen(true);
      return;
    }
    const observer = new IntersectionObserver(([entry]) =>
      setOnScreen(entry.isIntersecting)
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);

  useEffect(() => {
    const update = () => setPageVisible(document.visibilityState !== 'hidden');
    update();
    document.addEventListener('visibilitychange', update);
    return () => document.removeEventListener('visibilitychange', update);
  }, []);

  return onScreen && pageVisible && !paused;
}
